<?php
require_once __DIR__.'/includes/session_bootstrap.php'; startVfnWebSession();
require_once __DIR__.'/execute/config.php'; require_once __DIR__.'/includes/language.php';
require_once __DIR__.'/includes/web_session.php'; require_once __DIR__.'/includes/csrf.php';
require_once __DIR__.'/includes/chat_system.php'; require_once __DIR__.'/includes/web_features_schema.php';
function h($value):string{return htmlspecialchars((string)$value,ENT_QUOTES,'UTF-8');}
$pdo=new PDO("mysql:host=$dbHost;dbname=$dbName;charset=utf8mb4",$dbUser,$dbPass,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);
if(empty($_SESSION['web_user_id'])||!validateVfnWebSession($pdo)){header('Location:index.php?type=error&message=login_required');exit;}
ensureWebFeatureSchema($pdo);$userId=(int)$_SESSION['web_user_id'];$csrf=csrfToken('web_messages');$error='';
$readStmt=$pdo->prepare("SELECT COALESCE(MAX(id),0) FROM chat_messages WHERE recipient_user_id=:uid AND sender_user_id<>:uid");$readStmt->execute(['uid'=>$userId]);$lastReadId=(int)$readStmt->fetchColumn();$pdo->prepare("INSERT INTO web_notification_state(user_id,last_private_message_id) VALUES(:uid,:mid) ON DUPLICATE KEY UPDATE last_private_message_id=VALUES(last_private_message_id)")->execute(['uid'=>$userId,'mid'=>$lastReadId]);
$targetId=max(0,(int)($_GET['user_id']??$_POST['target_user_id']??0));
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(!csrfIsValid($_POST['csrf']??null,'web_messages')){$error=t('csrf_invalid');}
 else{
  $text=trim((string)($_POST['message']??''));
  $target=$pdo->prepare("SELECT id,username FROM users WHERE id=:id AND is_active=1 LIMIT 1");$target->execute(['id'=>$targetId]);$targetUser=$target->fetch(PDO::FETCH_ASSOC);
  if(!$targetUser||$targetId===$userId||$text===''){$error=t('messages_send_failed');}
  else{
   $sender=$pdo->prepare("SELECT COALESCE((SELECT callsign FROM user_sessions WHERE user_id=:id AND callsign<>'' ORDER BY last_seen DESC LIMIT 1),username) FROM users WHERE id=:id");$sender->execute(['id'=>$userId]);$senderCallsign=(string)$sender->fetchColumn();
   insertChatMessage($pdo,null,$targetId,$userId,$senderCallsign,'system','[PM] '.mb_substr($text,0,240));
   insertChatMessage($pdo,null,$userId,$userId,'MSG','system','An '.$targetUser['username'].': '.mb_substr($text,0,220));
   header('Location:messages.php?user_id='.$targetId);exit;
  }
 }
}
$search=trim((string)($_GET['q']??''));$people=[];
if($search!==''){$s=$pdo->prepare("SELECT DISTINCT u.id,u.username,u.real_name,s.callsign FROM users u LEFT JOIN user_sessions s ON s.user_id=u.id AND s.is_active=1 WHERE u.id<>:uid AND (u.username LIKE :q OR u.real_name LIKE :q OR s.callsign LIKE :q) ORDER BY u.username LIMIT 20");$s->execute(['uid'=>$userId,'q'=>'%'.mb_substr($search,0,80).'%']);$people=$s->fetchAll(PDO::FETCH_ASSOC);}
$threads=$pdo->prepare("SELECT other_id,MAX(created_at) last_at,MAX(other_name) other_name FROM (
 SELECT sender_user_id other_id,created_at,sender_callsign other_name FROM chat_messages WHERE recipient_user_id=:uid AND sender_user_id<>:uid AND message_text LIKE '[PM]%'
 UNION ALL SELECT recipient_user_id other_id,created_at,'--' other_name FROM chat_messages WHERE sender_user_id=:uid AND recipient_user_id<>:uid AND message_text LIKE '[PM]%') x GROUP BY other_id ORDER BY last_at DESC LIMIT 40");$threads->execute(['uid'=>$userId]);$threadRows=$threads->fetchAll(PDO::FETCH_ASSOC);
foreach($threadRows as &$thread){$n=$pdo->prepare("SELECT username,real_name FROM users WHERE id=:id");$n->execute(['id'=>$thread['other_id']]);$thread['user']=$n->fetch(PDO::FETCH_ASSOC)?:['username'=>$thread['other_name'],'real_name'=>''];}unset($thread);
$conversation=[];$targetUser=null;if($targetId){$t=$pdo->prepare("SELECT id,username,real_name FROM users WHERE id=:id");$t->execute(['id'=>$targetId]);$targetUser=$t->fetch(PDO::FETCH_ASSOC);if($targetUser){$c=$pdo->prepare("SELECT * FROM chat_messages WHERE message_text LIKE '[PM]%' AND ((sender_user_id=:me AND recipient_user_id=:other) OR (sender_user_id=:other AND recipient_user_id=:me)) ORDER BY id DESC LIMIT 100");$c->execute(['me'=>$userId,'other'=>$targetId]);$conversation=array_reverse($c->fetchAll(PDO::FETCH_ASSOC));}}
?>
<!doctype html><html lang="<?php echo h($currentLanguage);?>"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?php echo h(t('messages_title'));?></title><style>body{margin:0;background:#07141f;color:#d7e8ff;font-family:Arial}.shell{width:min(1250px,calc(100% - 30px));margin:25px auto}.layout{display:grid;grid-template-columns:330px 1fr;gap:16px}.card{background:#0d1d2a;border:1px solid #285475;border-radius:8px;padding:16px}.hint,.empty{font-size:13px;color:#9ab0c3}.thread,.result{display:block;padding:10px;border-bottom:1px solid #203b50;color:#bde0ff;text-decoration:none}.thread.active,.thread:hover,.result:hover{background:#15354d}.messages{height:500px;overflow:auto;display:flex;flex-direction:column;gap:9px}.bubble{max-width:75%;padding:10px 12px;border-radius:8px;background:#18354a}.bubble.mine{align-self:flex-end;background:#176dcc}.meta{font-size:11px;color:#9ab0c3;margin-top:4px}input,textarea{box-sizing:border-box;width:100%;padding:10px;background:#071521;color:#fff;border:1px solid #285475;border-radius:4px}button{padding:10px 15px;background:#176dcc;color:#fff;border:0;border-radius:4px;margin-top:8px}@media(max-width:800px){.layout{grid-template-columns:1fr}.messages{height:380px}}</style></head><body><?php require __DIR__.'/includes/header.php';?><main class="shell"><h1><?php echo h(t('messages_title'));?></h1><div class="layout"><aside class="card"><h3><?php echo h(t('messages_new_conversation'));?></h3><p class="hint"><?php echo h(t('messages_search_hint'));?></p><form method="get"><input name="q" value="<?php echo h($search);?>" placeholder="<?php echo h(t('messages_search'));?>" autocomplete="off"></form><?php foreach($people as $p):?><a class="result" href="messages.php?user_id=<?php echo (int)$p['id'];?>"><?php echo h($p['callsign']?:$p['username']);?> &middot; <?php echo h($p['real_name']);?></a><?php endforeach;?><?php if($search!==''&&!$people):?><p class="empty"><?php echo h(t('messages_no_search_results'));?></p><?php endif;?><h3><?php echo h(t('messages_conversations'));?></h3><?php foreach($threadRows as $thread):?><a class="thread <?php echo $targetId==(int)$thread['other_id']?'active':'';?>" href="messages.php?user_id=<?php echo (int)$thread['other_id'];?>"><?php echo h($thread['user']['real_name']?:$thread['user']['username']);?><div class="meta"><?php echo h(date('d.m.Y H:i',strtotime($thread['last_at'])));?></div></a><?php endforeach;?></aside><section class="card"><?php if(!$targetUser):?><p><?php echo h(t('messages_select_conversation'));?></p><?php else:?><h2><?php echo h($targetUser['real_name']?:$targetUser['username']);?></h2><div class="messages"><?php foreach($conversation as $m):?><div class="bubble <?php echo (int)$m['sender_user_id']===$userId?'mine':'';?>"><?php echo h(preg_replace('/^\[PM\]\s*/','',$m['message_text']));?><div class="meta"><?php echo h($m['sender_callsign']);?> &middot; <?php echo h(date('d.m.Y H:i',strtotime($m['created_at'])));?></div></div><?php endforeach;?></div><?php if($error):?><p><?php echo h($error);?></p><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?php echo h($csrf);?>"><input type="hidden" name="target_user_id" value="<?php echo $targetId;?>"><textarea name="message" rows="3" required></textarea><button><?php echo h(t('messages_send'));?></button></form><?php endif;?></section></div></main><?php require __DIR__.'/includes/footer.php';?></body></html>
